export default {"html":"<p data-line=\"0\" class=\"code-line\">Photo sliders are a common mobile UI pattern for viewing photos. With limited screen space, they are often used to show images near full screen, zoomed in. You see them on X and Facebook too. In app development, \"expand photo + slider\" is genuinely useful. Because it is useful, when you maintain several apps you end up writing the same slider code in each one. How many identical photo sliders did I have across my apps back then—four, I think.</p>\n<p data-line=\"2\" class=\"code-line\">That hurts maintainability. Pause updates on one app and you wonder how far you got with migrating features. I extracted a library so every project can open a photo slider modal with one call. If you have had a similar experience, give it a try.</p>\n<h2 id=\"demo\" data-line=\"4\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#demo\" aria-hidden=\"true\"></a> Demo</h2>\n<p data-line=\"6\" class=\"code-line\"><a href=\"https://rdlabo-ionic-angular-library.netlify.app/main/photo-editor\" rel=\"noopener noreferrer\" target=\"_blank\">https://rdlabo-ionic-angular-library.netlify.app/main/photo-editor</a><a href=\"https://rdlabo-ionic-angular-library.netlify.app/main/photo-editor\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://rdlabo-ionic-angular-library.netlify.app/main/photo-editor</a></p>\n<p data-line=\"8\" class=\"code-line\">There is an editor too, but check \"Launch Photo Viewer.\" You will recognize it—the thing everyone implements.<br>\nThe demo shows \"Delete\" in the top right; you can hide it, and you can replace the label text.</p>\n<p data-line=\"11\" class=\"code-line\"><img src=\"/images/51b63e75b84da9/8d24f12a328c304d53cbc9988a69a466.gif\" alt=\"8d24f12a328c304d53cbc9988a69a466.gif\" class=\"md-img\" loading=\"lazy\"></p>\n<h2 id=\"usage\" data-line=\"14\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#usage\" aria-hidden=\"true\"></a> Usage</h2>\n<p data-line=\"16\" class=\"code-line\">Install in your Ionic Angular project first.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"18\"><span class=\"line\"><span style=\"color:#B392F0\">%</span><span style=\"color:#9ECBFF\"> npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#9ECBFF\"> @rdlabo/ionic-angular-photo-editor</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"22\" class=\"code-line\">Then add this to your global styles.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"24\"><span class=\"line\"><span style=\"color:#B392F0\">:root</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-background</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#2a2a2a</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-background-tint</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#414141</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#f0f0f0</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-color-tint</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#dbdbdb</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-primary</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#4d8dff</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-danger</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#f24c58</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-success</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#2dd55b</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"39\" class=\"code-line\">Styles use CSS variables, so you can theme them. Usage is simple: when opening an Ionic modal, pass photo data and the starting index via <code>ComponentProps</code>. Set <code>enableDelete</code> to <code>false</code> to hide the delete button.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"41\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { PhotoViewerPage, IPhotoViewerDismiss } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@rdlabo/ionic-angular-photo-editor'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> modal</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.modalCtrl.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    component: PhotoViewerPage,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    componentProps: {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      imageUrls: [</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        'https://picsum.photos/200/300'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        'https://picsum.photos/200/300'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      ],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      index: </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      isCircle: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      enableDelete: </span><span style=\"color:#79B8FF\">true</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> modal.</span><span style=\"color:#B392F0\">present</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">data</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> modal.</span><span style=\"color:#B392F0\">onWillDismiss</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">IPhotoViewerDismiss</span><span style=\"color:#E1E4E8\">&gt;();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (data?.delete) {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // User delete image</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})();</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"65\" class=\"code-line\">See <a href=\"https://github.com/rdlabo-dev/ionic-angular-library/tree/main/projects/photo-editor\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/rdlabo-dev/ionic-angular-library/tree/main/projects/photo-editor</a> for details.</p>\n<h2 id=\"summary\" data-line=\"67\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"69\" class=\"code-line\">I use this library in apps I ship, and it has been stable. Give it a try.</p>\n<p data-line=\"71\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"demo","text":"Demo","level":2},{"id":"usage","text":"Usage","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
